mapper.select:
                SELECT
                    sl.*,
                    su.username AS username,
                    sak.id AS sak_id,
                    sak.name AS sak_name
                FROM
                    sys_log sl
                    LEFT JOIN sys_user su ON sl.user_id = su.id
                    left join sys_api_key sak on sl.api_key_id = sak.id


                                AND sl.operation like CONCAT('%', #{params.operation}, '%')


                                AND sl.state = #{params.state}


                                AND sl.type like CONCAT('%', #{params.type}, '%')


                                AND sl.user_id IN

                                        #{id}



                                AND (su.name like CONCAT('%', #{params.name}, '%') or su.username like CONCAT('%', #{params.name}, '%'))


                                AND sl.ip = #{params.ip}


                        	AND sl.opera_id in

					       		#{id}



                        	AND sl.params = #{params.params}


                        	AND sl.response = #{params.response}


                        	AND sl.exception = #{params.exception}


                        	AND (su.name like CONCAT('%', #{params.q}, '%') or su.username like CONCAT('%', #{params.q}, '%') or sl.type like CONCAT('%', #{params.q}, '%') or sl.opera_id like CONCAT('%', #{params.q}, '%') or sl.ip like CONCAT('%', #{params.q}, '%') or sl.params like CONCAT('%', #{params.q}, '%') or sl.response like CONCAT('%', #{params.q}, '%') or sl.exception like CONCAT('%', #{params.q}, '%'))




                ORDER BY sl.ctime DESC
